CREATE TABLE nums (id INTEGER PRIMARY KEY, sq INTEGER, label TEXT);
BEGIN;
COMMIT;
SELECT COUNT(*), SUM(sq), MIN(id), MAX(id) FROM nums;
SELECT id, sq FROM nums WHERE id BETWEEN 1000 AND 3000;
SELECT COUNT(*) FROM nums WHERE sq < 1000;
DELETE FROM nums WHERE id % 3 = 0;
SELECT COUNT(*), SUM(id) FROM nums;
UPDATE nums SET label = 'even' WHERE id % 2 = 0;
SELECT label, COUNT(*) FROM nums WHERE label = 'even' GROUP BY label;
SELECT id FROM nums ORDER BY sq DESC, id LIMIT 5;
